import{c as t,Q as a,j as r,m as n}from"./chunks/framework.BqPkuuVc.js";const c=JSON.parse('{"title":"Live view","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/live-view.md","filePath":"user/running-the-event/live-view.md"}'),o={name:"user/running-the-event/live-view.md"};function i(s,e,h,l,d,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="live-view" tabindex="-1">Live view <a class="header-anchor" href="#live-view" aria-label="Permalink to &quot;Live view&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators and commentators who want to see the event on a map while it runs.</p><p>A map of the event as it happens: where meshO Prime and the radio controls are, where the tracked competitors are now, and how the radio network is linking them.</p><h2 id="opening-it" tabindex="-1">Opening it <a class="header-anchor" href="#opening-it" aria-label="Permalink to &quot;Opening it&quot;">​</a></h2><p>Open the event and choose <strong>Live view</strong> under <strong>Event live</strong>. It&#39;s there while the event is running, and only for an event that uses meshO Prime (<strong>Event details → Radio Controls → meshO Prime</strong>).</p><p>The map appears as soon as there&#39;s something to put on it: a meshO Control reporting a GPS fix, a meshO Athlete unit connecting, or a calibrated event map uploaded on the <strong>Map</strong> page. Until then it says <strong>Nothing to show on the map yet</strong>.</p><h2 id="what-s-on-the-map" tabindex="-1">What&#39;s on the map <a class="header-anchor" href="#what-s-on-the-map" aria-label="Permalink to &quot;What&#39;s on the map&quot;">​</a></h2><ul><li><strong>Prime</strong> — the base. When Prime reports its own GPS position it is pinned there. Otherwise it shows as <strong>Prime — drag to position</strong>: drag it to where Prime really is, so the radio links are drawn from the right place.</li><li><strong>Control units</strong> — each meshO Control, labelled with its control code. Hover for its unit number and battery.</li><li><strong>Athletes</strong> — each meshO Athlete unit at its latest position.</li></ul><h2 id="map-controls" tabindex="-1">Map controls <a class="header-anchor" href="#map-controls" aria-label="Permalink to &quot;Map controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Layer</strong></td><td>The base map: your <strong>Event map</strong> (when a calibrated map has been uploaded), <strong>Street</strong>, <strong>Satellite</strong> or <strong>Topographic</strong>.</td></tr><tr><td><strong>Opacity</strong></td><td>How strongly the event map is drawn over the layer beneath it.</td></tr><tr><td><strong>Magnetic north up</strong></td><td>Turns the map so magnetic north is up, as on an orienteering map.</td></tr><tr><td><strong>Fit all</strong></td><td>Zooms to fit everything on the map.</td></tr><tr><td><strong>Open in new tab</strong></td><td>The map on its own, for a second monitor or the commentary position.</td></tr></tbody></table><h3 id="athletes" tabindex="-1">Athletes <a class="header-anchor" href="#athletes" aria-label="Permalink to &quot;Athletes&quot;">​</a></h3><p>The <strong>Athletes</strong> panel lists every tracked unit. Turn individual athletes on or off to follow only the ones you&#39;re interested in, and open a unit&#39;s <strong>battery history</strong> from here. The <a href="./tracking">Tracking</a> screen has the same units as a table.</p><h3 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h3><p>The <strong>Controls</strong> panel has:</p><ul><li><strong>Show all controls</strong>, to show or hide them all at once, or one by one;</li><li><strong>Show control numbers</strong> on the map;</li><li><strong>Signal strength</strong>, which draws the recent radio links between Prime, the controls and the athletes. A link fades after 5 minutes without being heard and disappears after 10, so what&#39;s drawn is the network as it is now.</li></ul><p>A control&#39;s battery history opens from this panel too.</p><h2 id="during-a-replay" tabindex="-1">During a replay <a class="header-anchor" href="#during-a-replay" aria-label="Permalink to &quot;During a replay&quot;">​</a></h2><p>When a captured event is being replayed, the map follows the replay&#39;s clock: markers and links move at the replay speed rather than in real time. See <a href="./dashboard">The event dashboard</a>.</p><h2 id="live-view-or-tracking" tabindex="-1">Live view or Tracking? <a class="header-anchor" href="#live-view-or-tracking" aria-label="Permalink to &quot;Live view or Tracking?&quot;">​</a></h2><p><strong>Live view</strong> is the map: where things are. <a href="./tracking">Tracking</a> is the table: which trackers are reporting, their batteries, and Livelox.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./tracking">Tracking</a></li><li><a href="./connecting-prime-and-radios">Connecting meshO Prime and radios</a></li><li><a href="./radio-punches">Radio punches</a></li><li><a href="./../screens/commentary">Commentary</a></li></ul>',22)])])}const m=t(o,[["render",i]]);export{c as __pageData,m as default};
